function lnf(n){if(n<2)return 0;let s=0;if(n<1000){for(let i=2;i<=n;i++)s+=Math.log(i);return s;}return n*Math.log(n)-n+0.5*Math.log(2*Math.PI*n)+1/(12*n);}
