  const rows=all.filter(g=>(cls==="all"||(cls==="def"?g[2]>0:CL[g[2]]===cls))&&(!kw||(G.d[g[3]]||"").toLowerCase().includes(kw)||gidOf(c,g[1]).toLowerCase().includes(kw)));
  const recs=Object.values(st.reports).filter(r=>{const x=co(r,MAIN);if(!x||x.chr!==c)return false;const lo=x.start!==""&&x.start!=null?+x.start:(x.peak!=null&&x.peak!==""?+x.peak:null);const hi=x.end!==""&&x.end!=null?+x.end:lo;return lo!=null&&hi>=f&&lo<=t;});
