const EFF={"Tsn1":"ToxA (SnToxA / PtrToxA)","Tsn1-B1":"SnToxA","Tsn1-B2":"SnToxA / PtrToxA","Snn1":"SnTox1","Snn1-B1":"SnTox1","Snn1-B2":"SnTox1","Snn3-B2":"SnTox3","Snn2":"SnTox2","Snn3-B1":"SnTox3","Snn3-D1":"SnTox3","Snn4":"SnTox4","Snn5":"SnTox5","Snn5-B1":"SnTox5","Snn5-B2":"SnTox5","Snn2":"SnTox2 (SnTox267)","Snn6":"SnTox6 (SnTox267)","Snn7":"SnTox7 (SnTox267)","Tsc1":"Ptr ToxC","Tsc2":"Ptr ToxB","SnTox3":"SnTox3"};
function sgBase(n){let s=String(n).replace(/\s*\(.*$/,"").replace(/\s+region$/,"").trim();const m=s.match(/^(Tsn1-B\d|Tsn1|Snn\d(?:-[BD]\d)?|Tsc\d|Sb\d|SnTox\d)/i);const k=m?m[1]:s;return ({"Tsn1":"Tsn1-B1","Snn1":"Snn1-B1","Snn3":"Snn3-B1","Snn5":"Snn5-B1"})[k]||k;}
