function alertMsg(t){$("#papNote").textContent=t;$("#papNote").style.color="var(--bad)";}
function setStatus(kind,text){$("#dot").className="dot "+kind;$("#statusText").textContent=text;}
/* ---------- db ---------- */
async function connect(){if(!window.claude||!window.claude.use){return;}
  let db=null;try{db=await window.claude.use("db");}catch(e){}
  if(!db){setStatus("snap","Read-only snapshot (sign in to see live edits)");return;}
  st.db=db;let user=null;try{user=await window.claude.use("user");}catch(e){}st.user=user;
  if(user){try{st.uid=await user.id();}catch(e){}try{const c=await user.can("data.write");st.canWrite=c!==false;}catch(e){st.canWrite=true;}try{st.canEdit=!!(await user.canEdit());}catch(e){}}else{st.canWrite=true;}
  $("#addBtn").hidden=!st.canWrite;
  let got=0;const timer=setTimeout(()=>{if(!st.live)setStatus("snap","Live database not reachable yet; showing release v1.2");},10000);
  const sub=(coll,apply)=>db.collection(coll).onSnapshot(snap=>{
      if(!snap.empty){apply(snap);}if(!snap.metadata.fromCache){got++;if(got>=1){clearTimeout(timer);st.live=true;setStatus("live",`Live database${st.canWrite?" · you can edit":" · read only"}`);}}renderAll();},
    err=>{clearTimeout(timer);setStatus("snap","Live updates stopped; showing the last data loaded");});
  sub("reports",snap=>{const o={};SEED.reports.forEach(r=>o[r.id]=r);snap.docs.forEach(d=>{const x=d.data();if(x.deleted)delete o[d.id];else o[d.id]={...(o[d.id]||{}),...x,id:d.id};});st.reports=o;});
  sub("sources",snap=>{const o={...SEED.sources};snap.docs.forEach(d=>{o[d.id]=SEED.sources[d.id]?{...d.data(),...SEED.sources[d.id]}:d.data();});st.sources=o;renderAll();});
  sub("papers",snap=>{const o={};snap.docs.forEach(d=>o[d.id]={...d.data(),id:d.id});st.papers=o;});
  db.collection("changes").orderBy("at","desc").limit(40).onSnapshot(snap=>{st.changes=snap.docs.map(d=>d.data());if(location.hash==="#about")renderChanges();},()=>{});}

/* ---- Candidate gene mapping (computed live from the current records) ---- */
let GENES=null;function genesAll(){if(GENES)return GENES;try{GENES=JSON.parse(document.getElementById("genesall").textContent);}catch(e){GENES={cl:[],d:[],g:{}};}return GENES;}
const GWT={A:3,B:2,C:1.5,D:0.5};
function fmFill(){const s=$("#fmChr");if(s&&!s.options.length){CHRS.forEach(c=>s.insertAdjacentHTML("beforeend",`<option${c==="5B"?" selected":""}>${c}</option>`));}}
function fineMap(){const out=$("#fmOut");if(!out)return;try{fineMapRun(out);}catch(e){out.innerHTML=`<p class="msg err">Candidate gene mapping could not run: ${esc(String(e&&e.message||e))}</p>`;console.error(e);}}
function fineMapRun(box){fmFill();
  const A=MAIN,CL=ALEN[A]||CHR,c=$("#fmChr").value||"5B",f=num($("#fmFrom").value)??0,t=num($("#fmTo").value)??CL[c],pad=num($("#fmPad").value)??0;
  if(!Object.keys(st.reports||{}).length){box.innerHTML=`<p class="small muted">Records are still loading; press “Map candidate genes” again in a moment.</p>`;return;}
  const ev=[];Object.values(st.reports).forEach(r=>{if(!anchored(r,A)||co(r,A).chr!==c)return;const c0=co(r,A),s=num(c0.start),e=num(c0.end),p=pos(r,A);
    let lo=(s!=null&&e!=null?Math.min(s,e):p),hi=(s!=null&&e!=null?Math.max(s,e):p);if(hi+pad<f||lo-pad>t)return;
    const pk=num(c0.peak);ev.push({r,lo,hi,pk:pk!=null?pk:null,w:GWT[r.grade]||1,pt:(hi-lo)<=0.5});});
  if(!ev.length){box.innerHTML=`<p>No positioned loci in ${esc(c)} ${fmt(f)}–${fmt(t)} Mb.</p>`;return;}
  const L0=Math.max(0,f-pad),L1=Math.min(CL[c],t+pad),span0=Math.max(0.1,L1-L0);
  const bw=Math.max(0.05,span0/400),nb=Math.ceil(span0/bw)+1,den=new Array(nb).fill(0),cov=new Array(nb).fill(0);
  const bi=x=>Math.max(0,Math.min(nb-1,Math.floor((x-L0)/bw)));
  ev.forEach(x=>{const a=bi(x.lo),b=bi(x.hi);for(let i=a;i<=b;i++)cov[i]++;
    if(x.pt||x.pk!=null){const q=x.pk!=null?x.pk:(x.lo+x.hi)/2;const k=bi(q),sp=Math.max(1,Math.round(0.25/bw));for(let i=Math.max(0,k-sp);i<=Math.min(nb-1,k+sp);i++)den[i]+=x.w*3/(2*sp+1);}
    if(!x.pt){const n=b-a+1;for(let i=a;i<=b;i++)den[i]+=x.w/n;}});
  const sm=den.map((v,i)=>{let s=0,n=0;for(let j=i-2;j<=i+2;j++)if(j>=0&&j<nb){s+=den[j];n++;}return s/n;});
  const mx=Math.max(...sm);const k=sm.indexOf(mx);let a=k,b=k;while(a>0&&sm[a-1]>=0.5*mx)a--;while(b<nb-1&&sm[b+1]>=0.5*mx)b++;
  let cLo=L0+a*bw,cHi=L0+(b+1)*bw;
  const G=genesAll(),CLN=G.cl,gch=(G.g&&G.g[c])||[];
  // make sure the core holds genes: widen symmetrically until at least 3 genes (max 2 Mb each side)
  let widen=0;const inC=()=>gch.filter(g=>g[0]>=cLo&&g[0]<=cHi).length;while(inC()<3&&widen<2){cLo-=0.1;cHi+=0.1;widen+=0.1;}
  cLo=Math.max(L0,cLo);cHi=Math.min(L1,cHi);
  const inCore=ev.filter(x=>x.hi>=cLo&&x.lo<=cHi);const dset=[...new Set(inCore.map(x=>x.r.disease))];const studies=new Set(inCore.map(x=>x.r.source)).size;
  const mxCov=Math.max(...cov),covIdx=cov.indexOf(mxCov);
  const pts=inCore.filter(x=>x.pt||x.pk!=null).map(x=>x.pk!=null?x.pk:(x.lo+x.hi)/2);
  const gid=n=>`TraesCS${c}02G${String(n).padStart(6,"0")}`;
  const gl=gch.filter(g=>g[0]>=cLo&&g[0]<=cHi).map(g=>({p:g[0],id:gid(g[1]),id21:gid21(c,g),cl:CLN[g[2]]||"other",d:G.d[g[3]]||"",def:g[2]>0,dist:pts.length?Math.min(...pts.map(q=>Math.abs(q-g[0]))):null}))
    .sort((x,y)=>(y.def-x.def)||((x.dist??99)-(y.dist??99))||x.p-y.p);
  const nDef=gl.filter(x=>x.def).length;
  const W=700,H=120,sx=x=>((x-L0)/span0)*W;const maxD=Math.max(...sm,1e-9);
  const path=sm.map((v,i)=>`${i?"L":"M"}${(sx(L0+i*bw)).toFixed(1)},${(H-20-(v/maxD)*(H-30)).toFixed(1)}`).join("");
  const ticks=[0,0.25,0.5,0.75,1].map(q=>{const x=L0+q*span0;return `<text x="${sx(x).toFixed(0)}" y="${H-4}" font-size="10" text-anchor="${q===0?"start":q===1?"end":"middle"}" fill="var(--muted)">${x.toFixed(1)}</text>`;}).join("");
  const svg=`<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Evidence density along ${c}"><rect x="${sx(cLo).toFixed(1)}" y="0" width="${Math.max(2,sx(cHi)-sx(cLo)).toFixed(1)}" height="${H-18}" fill="var(--accent,#2b7a5b)" opacity=".15"/>
   <path d="${path}" fill="none" stroke="var(--accent,#2b7a5b)" stroke-width="2"/>${ev.filter(x=>x.pt||x.pk!=null).map(x=>`<circle cx="${sx(x.pk!=null?x.pk:(x.lo+x.hi)/2).toFixed(1)}" cy="${H-20}" r="3" fill="${DCOL[x.r.disease]||"#888"}"><title>${esc(x.r.name)} (${esc(x.r.disease)})</title></circle>`).join("")}${ticks}</svg>`;
  const trimmed=Math.max(0,100*(1-(cHi-cLo)/span0));
  box.innerHTML=`<h3 style="margin:6px 0 4px;font-size:16px">${esc(c)} ${fmt(f)}–${fmt(t)} Mb</h3>
   <p class="small muted" style="margin:0 0 10px">${ev.length} positioned report(s) overlap this region (curve: weighted evidence along ${esc(c)}; shaded: candidate core region; dots: precise loci coloured by disease).</p>${svg}
   <div class="row" style="gap:16px;flex-wrap:wrap;margin:8px 0">
    <div><b>Candidate core region</b><br>${cLo.toFixed(2)}–${cHi.toFixed(2)} Mb (${(cHi-cLo).toFixed(2)} Mb)${widen>0?`<div class="small muted">widened by ${widen.toFixed(1)} Mb each side to include genes</div>`:""}</div>
    <div><b>Sequence trimmed</b><br>${trimmed.toFixed(0)}% of the ${span0.toFixed(1)} Mb searched</div>
    <div><b>Supporting reports</b><br>${inCore.length} from ${studies} source(s)</div>
    <div><b>Max overlapping loci</b><br>${mxCov} at ${(L0+covIdx*bw).toFixed(1)} Mb</div></div>
   <p class="small"><button class="btn" type="button" id="fmSeq">Show nucleotide sequence of the core in the Region sequence viewer →</button></p><div id="fmSeqOut"></div>
   <p><b>Diseases at the core:</b> ${dset.map(d=>`<span class="dchip"><span class="sw" style="background:${DCOL[d]}"></span>${esc(d)}</span>`).join(" ")}${dset.length>1?` <span class="small">→ candidate shared (multi-disease) locus</span>`:""}</p>
   <h3 style="margin:10px 0 4px;font-size:14px">Candidate genes in the core region: ${gl.length} high-confidence gene(s), ${nDef} defence-related</h3>
   ${gl.length?`<div style="max-height:320px;overflow:auto"><table class="tbl"><thead><tr><th>Gene (IWGSC v1.1 ID)</th><th>Class</th><th class="r">Mb (v2.1)</th><th class="r">To nearest precise locus</th><th>Description</th></tr></thead><tbody>${gl.slice(0,150).map(o=>`<tr${o.def?' style="background:var(--hl,#fff7e0)"':""}><td class="mono">${esc(o.id)}${o.id21?`<div class="small muted">${esc(o.id21)}</div>`:""}</td><td>${o.def?"<b>"+esc(o.cl)+"</b>":"–"}</td><td class="num">${o.p.toFixed(2)}</td><td class="num">${o.dist!=null?o.dist.toFixed(2)+" Mb":"–"}</td><td class="small">${esc(o.d)}</td></tr>`).join("")}</tbody></table></div>${gl.length>150?`<p class="small muted">First 150 of ${gl.length} genes shown (defence-related first).</p>`:""}`:`<p class="small">No annotated high-confidence genes in the core.</p>`}
   ${nDef?"":(()=>{const fl=gch.filter(g=>g[2]>0&&(g[0]<cLo||g[0]>cHi)&&g[0]>=cLo-2&&g[0]<=cHi+2).map(g=>({g,d:Math.min(Math.abs(g[0]-cLo),Math.abs(g[0]-cHi))})).sort((x,y)=>x.d-y.d).slice(0,10);return fl.length?`<p class="small" style="margin:6px 0"><b>No defence-related gene inside the core. Nearest ones within 2 Mb:</b> ${fl.map(o=>`<span class="mono">${esc(gid(o.g[1]))}</span> (${esc(CLN[o.g[2]])}, ${o.g[0].toFixed(2)} Mb, ${o.d.toFixed(2)} Mb from core)`).join("; ")}</p>`:"";})()}
   <p class="small muted">Defence-related genes (NLR, WAK, receptor kinases, PR proteins, ABC transporters, other kinases) are highlighted and listed first, then by distance to the nearest precise locus. Overlapping positions suggest, but do not prove, a single gene; tightly linked genes can look the same. Treat these as prioritised candidates.</p>
   <h3 style="margin:10px 0 4px;font-size:14px">Reports supporting the core</h3>
   <div style="max-height:220px;overflow:auto"><table class="tbl"><thead><tr><th>Locus</th><th>Disease</th><th class="r">Interval / peak</th><th>Grade</th><th>Reference</th></tr></thead><tbody>${inCore.sort((x,y)=>x.lo-y.lo).map(x=>`<tr><td>${esc(x.r.name)}</td><td>${esc(x.r.disease)}</td><td class="num">${span(x.r,A)}</td><td>${esc(x.r.grade)}</td><td class="small">${srcLink(x.r.source)}</td></tr>`).join("")}</tbody></table></div>`;

  const sb=$("#fmSeq");if(sb)sb.onclick=()=>{if(window.__seqGo)window.__seqGo(c,cLo,cHi);else showSeq(c,cLo,cHi,$("#fmSeqOut"));};}
function fmHook(){fmFill();const b=$("#rFM");if(b)b.onclick=()=>{fmFill();$("#fmChr").value=$("#rChr").value;$("#fmFrom").value=$("#rFrom").value;$("#fmTo").value=$("#rTo").value;$("#fmPad").value=$("#rPad").value;if(location.hash!=="#finemap")location.hash="#finemap";else route();setTimeout(fineMap,30);};const g=$("#fmGo");if(g)g.onclick=fineMap;}

fmHook();

/* ---- Nucleotide sequence of a region (Chinese Spring) ---- */
function v21to10(c,p){const G=genesAll(),g=((G.g&&G.g[c])||[]).filter(x=>x[4]>=0);if(!g.length)return null;
  let lo=0,hi=g.length-1;while(lo<hi){const m=(lo+hi)>>1;if(g[m][0]<p)lo=m+1;else hi=m;}
  const nb=g.slice(Math.max(0,lo-3),lo+3).sort((x,y)=>Math.abs(x[0]-p)-Math.abs(y[0]-p)).slice(0,4);if(!nb.length)return null;
  const s=nb.slice().sort((x,y)=>x[0]-y[0]);let inc=0;for(let i=1;i<s.length;i++)if(s[i][4]>=s[i-1][4])inc++;const sl=inc>=(s.length-1)/2?1:-1;
  const b=nb[0];return b[4]/1000+sl*(p-b[0]);}
const SEQMAX=100000;const NCBIACC={"1A":"LS992080.1","1B":"LS992081.1","1D":"LS992082.1","2A":"LS992083.1","2B":"LS992084.1","2D":"LS992085.1","3A":"LS992086.1","3B":"LS992087.1","3D":"LS992088.1","4A":"LS992089.1","4B":"LS992090.1","4D":"LS992091.1","5A":"LS992092.1","5B":"LS992093.1","5D":"LS992094.1","6A":"LS992095.1","6B":"LS992096.1","6D":"LS992097.1","7A":"LS992098.1","7B":"LS992099.1","7D":"LS992100.1"};
/* Sequence source: 1) the atlas's own copy of the Chinese Spring RefSeq v2.1 genome on the host server
   (genome/v2.1/<chr>.seq = one line of sequence per chromosome, read with HTTP Range requests; exact v2.1 coordinates);
   2) otherwise NCBI (RefSeq v1.0, converted through anchor genes). */
const GENOME_BASE="genome/v2.1/";
async function getSeq(c,s21,e21){if(s21>e21)[s21,e21]=[e21,s21];const errs=[];
  try{const s=Math.max(1,Math.round(s21*1e6)),e=Math.round(e21*1e6);const r=await fetch(GENOME_BASE+c+".seq",{headers:{Range:`bytes=${s-1}-${e-1}`}});
    if(r.status===206){const sq=(await r.text()).trim().toUpperCase();if(sq&&!/[^ACGTN]/.test(sq.slice(0,200)))return {sq,s,e,asm:"IWGSC RefSeq v2.1",coord:`chr${c}:${s.toLocaleString()}–${e.toLocaleString()} (RefSeq v2.1)`,id:`chr${c}:${s}-${e} Triticum aestivum Chinese Spring IWGSC RefSeq v2.1`};}
    errs.push("own genome copy not found");}catch(x){errs.push("own genome copy not reachable");}
  const a=v21to10(c,s21),b=v21to10(c,e21);if(a==null||b==null)throw new Error("could not convert the region to RefSeq v1.0");
  const s=Math.max(1,Math.round(Math.min(a,b)*1e6)),e=Math.round(Math.max(a,b)*1e6);
  try{const r=await fetch(`https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi?db=nuccore&id=${NCBIACC[c]}&rettype=fasta&seq_start=${s}&seq_stop=${e}`);if(!r.ok)throw new Error("HTTP "+r.status);
    const sq=(await r.text()).split("\n").filter(l=>l&&l[0]!==">").join("").trim().toUpperCase();if(!sq)throw new Error("empty");
    return {sq,s,e,asm:"IWGSC RefSeq v1.0",coord:`chr${c}:${s.toLocaleString()}–${e.toLocaleString()} (RefSeq v1.0, converted through anchor genes)`,id:`chr${c}:${s}-${e} Triticum aestivum Chinese Spring IWGSC RefSeq v1.0 (= ${c} ${s21}-${e21} Mb on RefSeq v2.1)`};}
  catch(x){errs.push("public sequence service not reachable");}
  const er=new Error(errs.join("; "));er.offline=true;throw er;}
const SEQ_OFFLINE=`This preview of the atlas runs in a protected page that may not contact other servers, so the genome sequence cannot be read here. On the RGU server the sequence is read from the atlas's own copy of the Chinese Spring RefSeq v2.1 genome (folder genome/v2.1/; see About &amp; changes → Deployment), so this viewer and the primer tool work without any outside service.`;
async function showSeq(c,s21,e21,el){
  if(!el)return;if(s21>e21)[s21,e21]=[e21,s21];const len=Math.round((e21-s21)*1e6)+1;
  const a10=v21to10(c,s21),b10=v21to10(c,e21);let ncbi="",ens="";if(a10!=null&&b10!=null){const s=Math.max(1,Math.round(Math.min(a10,b10)*1e6)),e=Math.round(Math.max(a10,b10)*1e6);ncbi=`https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi?db=nuccore&id=${NCBIACC[c]}&rettype=fasta&seq_start=${s}&seq_stop=${e}`;ens=`https://plants.ensembl.org/Triticum_aestivum/Location/View?r=${c}:${s}-${e}`;
    var v10txt=`chr${c}:${s.toLocaleString()}–${e.toLocaleString()} on RefSeq v1.0`;}
  const head=`<p class="small">Region ${esc(c)} ${fmt(s21)}–${fmt(e21)} Mb on RefSeq v2.1 (${len.toLocaleString()} bp)${ncbi?` = <b>${v10txt}</b> (converted through the nearest anchor genes). <a href="${ncbi}" target="_blank" rel="noopener">Download FASTA (NCBI, ${NCBIACC[c]})</a> · <a href="${ens}" target="_blank" rel="noopener">Open in Ensembl Plants</a>`:""}</p>`;
  if(len>SEQMAX){el.innerHTML=head+`<p class="small muted">The region is longer than ${SEQMAX/1000} kb, so it is not shown on the page; use “Download FASTA” above (any length) or narrow the region.</p>`;return;}
  el.innerHTML=head+`<p class="small muted">Loading sequence…</p>`;
  try{const R=await getSeq(c,s21,e21),sq=R.sq;const gc=100*(sq.match(/[GC]/g)||[]).length/sq.length,n=(sq.match(/N/g)||[]).length;
    const fasta=`>${R.id}\n`+sq.replace(/(.{60})/g,"$1\n");
    el.innerHTML=head+`<p class="small">${esc(R.coord)} · ${sq.length.toLocaleString()} bp · GC ${gc.toFixed(1)}% · N ${n.toLocaleString()} <button class="btn" type="button" id="seqCopy">Copy FASTA</button> <button class="btn" type="button" id="seqDl">Save .fa</button></p><div class="seqbox" id="seqTxt"></div>`;
    $("#seqTxt").textContent=fasta;
    $("#seqCopy").onclick=()=>{try{navigator.clipboard.writeText(fasta);$("#seqCopy").textContent="Copied";}catch(e){}};
    $("#seqDl").onclick=()=>saveText(`WheatNHR_${c}_${R.s}-${R.e}.fa`,fasta);
  }catch(err){el.innerHTML=head+(err.offline?"":`<p class="msg">${esc(String(err.message||err))}</p>`);}
}

function seqHook(){const b=$("#sqGo");if(b)b.onclick=()=>{const c=$("#sqChr").value,f=num($("#sqFrom").value),t=num($("#sqTo").value);if(f==null||t==null)return;showSeq(c,f,t,$("#sqOut"));};
  const s=$("#sqChr");if(s&&!s.options.length)CHRS.forEach(c=>s.insertAdjacentHTML("beforeend",`<option${c==="5B"?" selected":""}>${c}</option>`));
  const go=(c,f,t)=>{$("#sqChr").value=c;$("#sqFrom").value=(+f).toFixed(3);$("#sqTo").value=(+t).toFixed(3);if(location.hash!=="#sequence")location.hash="#sequence";else route();setTimeout(()=>showSeq(c,+f,+t,$("#sqOut")),50);};
  const rs=$("#rSQ");if(rs)rs.onclick=()=>go($("#rChr").value,num($("#rFrom").value)??0,num($("#rTo").value)??0);window.__seqGo=go;}

seqHook();

/* ---- quick-start cards ---- */
function qsHook(){document.querySelectorAll(".qsb").forEach(btn=>btn.addEventListener("click",()=>{const k=btn.dataset.qs;
  const go=(el,focus)=>{if(!el)return;el.scrollIntoView({behavior:"smooth",block:"center"});const p=el.closest(".panel,.filters")||el;p.classList.remove("flash");void p.offsetWidth;p.classList.add("flash");if(focus)setTimeout(()=>focus.focus(),400);};
  if(k==="1"){go($("#ideo"),$("#q"));}
  else if(k==="2"){go($("#fCls"),$("#fCls"));}
  else if(k==="3"){const r=$("#tbl tbody tr[data-id]");go($("#tbl"));if(r)setTimeout(()=>r.click(),500);}}));}
function showAppErr(e){const p=$("#appErr");if(p){p.hidden=false;p.textContent="Part of the page could not load: "+String(e&&e.message||e)+". Please reload the page.";}console.error(e);}
window.addEventListener("error",ev=>showAppErr(ev.error||ev.message));

qsHook();
const EXTJSON=[['gokegg','gokegg_lite.json'],['markerslite','markers_lite.json'],['genesall','genes_all.json']];
(async function(){
  for(const it of EXTJSON){
    const el=document.getElementById(it[0]);
    if(el && !el.textContent.trim()){
      try{ const r=await fetch(it[1]); if(r.ok){ el.textContent=await r.text(); } }
      catch(e){ console.warn('could not load',it[1],e); }
    }
  }
  init();
})();
